  ('e32affaa-9ccc-41c8-aad6-94bac470ea53', $$Scheikunde$$, $$VWO$$, $$Mauveïne$$, $$VWO Scheikunde 2018-II$$),
  ('44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$Scheikunde$$, $$VWO$$, $$Stroom uit hout$$, $$VWO Scheikunde 2018-II$$),
  ('78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$Scheikunde$$, $$VWO$$, $$Haarverf$$, $$VWO Scheikunde 2018-II$$),
  ('355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$Scheikunde$$, $$VWO$$, $$Van afvalgas naar brandstof$$, $$VWO Scheikunde 2018-II$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('c1d7aa05-06d8-4b59-9ca7-649f1e5e55d3', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$inleiding — ontdekking van mauveïne door Perkin$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context1.png$$,
   $$In 1856 probeerde William Perkin kinine, een medicijn tegen malaria, te synthetiseren. Hij verkreeg geen kinine maar een mengsel met een paarse kleur. In de reactie was een paarse kleurstof gevormd, die later geschikt bleek om textiel te verven. Perkin noemde deze stof mauveïne en deze toevallige ontdekking werd een mijlpaal in de geschiedenis van de textielverf. In 1994 onderzocht men de samenstelling van de paarse kleurstof uit verschillende historische textielmonsters. De kleurstof bleek een mengsel te zijn van verwante verbindingen, waaronder mauveïne A, B, B2 en C. Perkin gebruikte voor de synthese drie organische beginstoffen en een oxidator. Hieronder zijn de structuurformules van de organische beginstoffen weergegeven.$$, 'inline'),
  ('ea397c7f-1c43-40bf-a10d-264e429e00be', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$aniline, o-toluïdine en p-toluïdine — structuurformules$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context2.png$$,
   $$De structuurformules van de drie organische beginstoffen: aniline (benzeenring met een NH₂-groep), o-toluïdine (benzeenring met een NH₂-groep en op de ortho-positie een CH₃-groep) en p-toluïdine (benzeenring met een NH₂-groep en op de para-positie een CH₃-groep).$$, 'inline'),
  ('3bd18023-a20d-4010-8dc1-22df5fd17f1a', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$mauveïne B bevat delen van de drie beginstoffen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context3.png$$,
   $$Op de uitwerkbijlage is de structuurformule van mauveïne B weergegeven. In de structuur van mauveïne B is de oorspronkelijke structuur van de drie organische beginstoffen te herkennen.$$, 'inline'),
  ('bf876cf1-cc2c-412b-9e8f-fc048c361f6c', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$uitwerkbijlage vraag 1 — structuurformule mauveïne B$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context4-uitwerkbijlage-vraag1.png$$,
   $$uitwerkbijlage bij vraag 1: structuurformule van mauveïne B, opgebouwd uit een centraal fenazinium-ringsysteem (met een positief geladen N-atoom) waaraan een CH₃-groep, een NH₂-groep, een fenylgroep, een NH-tolylgroep en een tweede NH₂-groep zijn gebonden — hierin zijn delen van aniline, o-toluïdine en p-toluïdine te herkennen.$$, 'uitwerkbijlage'),
  ('94ddc726-fb09-482f-ab54-912b2067ac33', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$chromatografie — hydrofobe kolom en methanol als mobiele fase$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context5.png$$,
   $$In het onderzoek van de monsters mauveïne is gebruikgemaakt van chromatografie. De onderzoekers gebruikten daarbij een hydrofobe stationaire fase en methanol als mobiele fase. De structuurformules van de drie stoffen die het meest in het paarse mengsel aanwezig zijn, zijn hieronder weergegeven.$$, 'inline'),
  ('718d54bf-b157-4410-94cd-ad6673bc9c67', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$structuurformules van mauveïne A, B en C$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context6.png$$,
   $$De structuurformules van mauveïne A, mauveïne B en mauveïne C: alle drie hebben hetzelfde fenazinium-grondskelet met een fenylgroep en een NH-tolylgroep, maar ze verschillen in het aantal CH₃-groepen op de aromatische ringen (mauveïne A heeft er één, mauveïne B twee en mauveïne C drie).$$, 'inline'),
  ('34d85e58-1f6e-4cd7-a07f-a137233d7a74', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$massaspectrum van het mengsel mauveïnes van Perkin$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context7.png$$,
   $$Van het mengsel van mauveïnes van Perkin is een massaspectrum gemaakt. Met de gebruikte techniek zagen de onderzoekers alleen de pieken van de molecuulionen van de mauveïnes. De gegevens van de mauveïnes A, B en C afkomstig uit het massaspectrum zijn in onderstaande tabel gegeven.$$, 'inline'),
  ('37868253-f36e-418d-9e0c-45bf793a40a5', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$tabel — m/z en intensiteit van mauveïne A, B en C$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context8.png$$,
   $$tabel: m/z-waarde en intensiteit van de molecuulionen van mauveïne A, B en C. Mauveïne A: m/z = 390, intensiteit 94. Mauveïne B: m/z = 405, intensiteit 100. Mauveïne C: m/z = 420, intensiteit 77.$$, 'inline'),
  ('16c92738-a7c3-4b4a-b41e-b37aa1376ec9', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$synthese van mauveïne B2 op microschaal$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context9.png$$,
   $$De onderzoekers hebben mauveïne B2, een isomeer van mauveïne B, op microschaal gesynthetiseerd. Een molecuul mauveïne B2 wordt gevormd uit één molecuul aniline, één molecuul o-toluïdine en twee moleculen p-toluïdine. Zij hebben hiertoe 60 μL aniline, 60 μL o-toluïdine en 120 μL p-toluïdine laten reageren. Ze verkregen 12 mg mauveïne B2. De molaire massa van mauveïne B2 is 406 g mol⁻¹.$$, 'inline'),
  ('7ffa7005-51c6-4d46-afa5-8f61749f4f8a', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$tabel — dichtheid en molaire massa van aniline, o-toluïdine en p-toluïdine$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context10.png$$,
   $$tabel met dichtheid (g mL⁻¹) en molaire massa (g mol⁻¹) van aniline (1,022; 93,1), o-toluïdine (1,01; 107) en p-toluïdine (1,05; 107).$$, 'inline'),
  ('92c5c5a7-96c7-4466-a4f1-9f8ad2a3a8b4', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$mauveïne A — cis-trans-isomerie en grensstructuur$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context11.png$$,
   $$Bij nader onderzoek naar de structuur van de moleculen bleek dat mauveïne A in twee vormen voorkomt. Deze vormen kunnen worden opgevat als een cis- en een trans-isomeer. Op de uitwerkbijlage is de Lewisstructuur gegeven van mauveïne A en de onvolledige Lewisstructuur van een andere grensstructuur. In deze grensstructuur is de positieve lading verplaatst naar een ander N-atoom. In het molecuul is dan ook een andere C=N-binding aanwezig. Met behulp van deze grensstructuur kan het bestaan van cis-trans-isomerie in mauveïne A worden verklaard.$$, 'inline'),
  ('3cd5f383-4277-448e-b2e5-07578dd278b6', 'e32affaa-9ccc-41c8-aad6-94bac470ea53', $$uitwerkbijlage vraag 5 — onvolledige Lewisstructuur mauveïne A$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-mauveine-context12-uitwerkbijlage-vraag5.png$$,
   $$uitwerkbijlage bij vraag 5: volledige Lewisstructuur van mauveïne A (met een positief geladen N-atoom in het fenazinium-ringsysteem) en daarnaast de onvolledige Lewisstructuur van een grensstructuur van mauveïne A, waarin de positieve lading en de C=N-binding naar een ander N-atoom zijn verplaatst — aan te vullen met elektronenparen en formele ladingen.$$, 'uitwerkbijlage'),

  ('f3a01d89-50ab-4ce8-8238-5a705656c632', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$inleiding — brandstofcellen met enzymen, hydrolyse van amylose$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context1.png$$,
   $$In brandstofcellen die glucose of zetmeel gebruiken als energiebron worden enzymen gebruikt. Zo kan amylose in zetmeel met behulp van enzymen door hydrolyse worden omgezet tot glucose. Andere enzymen zetten vervolgens de glucose om. Op de uitwerkbijlage is de onvolledige reactievergelijking weergegeven van de gedeeltelijke hydrolyse van amylose.$$, 'inline'),
  ('4e7a645c-0b1b-4faf-9dee-6c66aad53fa0', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$uitwerkbijlage vraag 7 — onvolledige reactievergelijking hydrolyse amylose$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context2-uitwerkbijlage-vraag7.png$$,
   $$uitwerkbijlage bij vraag 7: onvolledige reactievergelijking van de gedeeltelijke hydrolyse van amylose — een fragment van drie aaneengeschakelde glucose-eenheden (verbonden via glycosidebindingen) reageert met water tot een korter fragment plus twee losse glucosemoleculen, aan te vullen met structuurformules.$$, 'uitwerkbijlage'),
  ('583b3a68-b6ed-4445-b953-efbb537338e7', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$ammonium-12-molybdofosfaat — bereiding uit ammonium-orthomolybdaat$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context3.png$$,
   $$Wetenschappers hebben een brandstofcel voor biomassa ontwikkeld waarin geen enzymen worden gebruikt. Met deze brandstofcel kan energie worden opgewekt uit biomassa waarvoor geen geschikte enzymen bestaan. In het onderzoek naar een geschikte brandstofcel is gebruikgemaakt van ammonium-12-molybdofosfaat. De verhoudingsformule van deze stof is (NH₄)₃PO₄(MoO₃)₁₂. Ammonium-12-molybdofosfaat wordt gemaakt door ammonium-orthomolybdaat ((NH₄)₂MoO₄) te verhitten in aanwezigheid van fosforzuur en salpeterzuur. Als bijproducten ontstaan waterdamp en ammoniumnitraat.$$, 'inline'),
  ('075db945-481b-4071-b7a0-bd75f13fd664', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$POM3– en rPOM3– — omzetting onder invloed van licht$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context4.png$$,
   $$In oplossingen van ammonium-12-molybdofosfaat komen ionen PO₄(MoO₃)₁₂³⁻ voor. Een ion PO₄(MoO₃)₁₂³⁻ wordt in de rest van deze opgave voorgesteld als POM³⁻. Het deeltje POM³⁻ kan worden beschouwd als een fosfaat-ion dat wordt omringd door twaalf eenheden molybdeen(VI)oxide (MoO₃). Elke eenheid MoO₃ bestaat uit drie oxide-ionen en een Mo(VI)-ion. Onder invloed van licht wordt een deeltje POM³⁻ omgezet tot het zeer reactieve deeltje rPOM³⁻, dat snel reageert met allerlei organische stoffen. De structuur van POM³⁻ en rPOM³⁻ is gelijk, de deeltjes verschillen alleen in de verdeling van de elektronen binnen het deeltje. Bij de omzetting van POM³⁻ tot rPOM³⁻ wordt binnen een eenheid MoO₃ één elektron van één oxide-ion overgedragen naar de N-schil van één Mo(VI)-ion.$$, 'inline'),
  ('1a855812-2693-4a9e-af84-0de569d50d76', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$uitwerkbijlage vraag 9 — elektronenschillen oxide-ion en molybdeen-ion in rPOM3–$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context5-uitwerkbijlage-vraag9.png$$,
   $$uitwerkbijlage bij vraag 9: twee lege tabellen om het aantal elektronen per schil (K, L, M, N, O) in te vullen — één voor het omgezette oxide-ion en één voor het omgezette molybdeen-ion in reactief rPOM³⁻. Bij het molybdeen-ion is de O-schil al ingevuld met 0 elektronen.$$, 'uitwerkbijlage'),
  ('b19de2f3-fcc0-447e-ae00-29016e0e5eb6', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$lignine — omzetting met ammonium-12-molybdofosfaat (stap 1 en stap 2)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context6.png$$,
   $$In hout is onder andere het biopolymeer lignine aanwezig. Lignine is een netwerkpolymeer dat in brandstofcellen niet kan worden omgezet met enzymen. Met het gebruikte ammonium-12-molybdofosfaat kan lignine wel worden omgezet, zodat zelfs houtafval kan worden gebruikt in een brandstofcel. Op de uitwerkbijlage is een van de optredende omzettingen weergegeven. In stap 1 treedt oxidatie van lignine op. In stap 2 wordt het omcirkelde H-atoom als een H⁺-ion afgesplitst. Tevens wordt dan een C–C-binding verbroken en een H⁺-ion opgenomen. Dit H⁺-ion is weergegeven in het kader.$$, 'inline'),
  ('b48231e8-aaf3-4953-890e-066045129007', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$uitwerkbijlage vraag 10 — verplaatsing van elektronenparen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context7-uitwerkbijlage-vraag10.png$$,
   $$uitwerkbijlage bij vraag 10: reactieschema van de omzetting van lignine (stap 1: oxidatie; stap 2: verbreking van een C–C-binding met afsplitsing van een H⁺-ion en opname van een ander H⁺-ion), met een omkaderd deel waarin met pijlen de verplaatsing van elektronenparen moet worden aangegeven.$$, 'uitwerkbijlage'),
  ('fb092888-d045-47a7-a03a-1820045f7feb', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$opstelling — reactor, zonlicht en brandstofcel$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context8.png$$,
   $$In onderstaande figuur is de gebruikte opstelling schematisch weergegeven. In een lichtdoorlatende reactor heeft men biomassa gemengd met ammonium-12-molybdofosfaat. De reactor is vervolgens in zonlicht geplaatst, zodat POM³⁻ onder invloed van licht wordt omgezet tot rPOM³⁻. Het rPOM³⁻ reageert met de biomassa, waarbij onder andere H₃POM³⁻ en CO₂ worden gevormd.$$, 'inline'),
  ('cc364094-c7cb-4c3c-a39a-f22ca5e77d19', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$figuur — schema van reactor en brandstofcel$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context9.png$$,
   $$figuur: schema van de opstelling met een lichtdoorlatende reactor (waarin zonlicht POM³⁻ omzet in rPOM³⁻, dat met biomassa reageert tot H₃POM³⁻ en CO₂) die via leidingen is verbonden met een brandstofcel (waarin POM³⁻, H₃POM³⁻, H⁺, H₂O en O₂ zijn aangegeven).$$, 'inline'),
  ('646f8019-c15e-4296-982b-9165dee5458f', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$H3POM3– wordt in de brandstofcel weer omgezet tot POM3–$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context10.png$$,
   $$Na verloop van tijd wordt het mengsel door de brandstofcel gepompt. Het in de reactor ontstane H₃POM³⁻ wordt in de brandstofcel weer omgezet tot POM³⁻.$$, 'inline'),
  ('9bccd461-d089-403f-86e9-2f331d525446', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', $$experimentgegevens — 20 mL 0,25 M oplossing, 80% omzetting, stroomsterkte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-stroom-uit-hout-context11.png$$,
   $$In het onderzoek is een hoeveelheid verdunde biomassa gemengd met 20 mL van een 0,25 M oplossing ammonium-12-molybdofosfaat. Nadat dit mengsel enige tijd in het zonlicht had gestaan, bleek dat 80% van alle rPOM³⁻ was omgezet tot H₃POM³⁻. Het mengsel werd door de brandstofcel gepompt tot alle ontstane H₃POM³⁻ weer was omgezet tot POM³⁻. De brandstofcel leverde gedurende 30 minuten een gemiddelde stroomsterkte van 0,530 A.$$, 'inline'),

  ('644f3295-38b6-419e-89e9-6b29866a1caf', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$inleiding — haar, keratine en 18-MEA$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context1.png$$,
   $$Haarverf moet hechten aan het haar, daarom is kennis van de moleculaire structuur van een haar belangrijk. De buitenkant van een haar bestaat uit schubben die de haar compleet bedekken. Aan het oppervlak van deze schubben zijn moleculen van het vetzuur 18-MEA gebonden aan het eiwit keratine. (Met een elektronenmicroscopische foto van de schubbenstructuur van een haar.)$$, 'inline'),
  ('c31a008d-2936-4e9e-b85b-9e413dd8a396', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$18-MEA — structuurformule en thio-esterbinding met cysteïne$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context2.png$$,
   $$Structuurformule van 18-MEA: een vetzuur met een carbonzuurgroep (COOH) aan een lange koolwaterstofketen. 18-MEA is aan keratine gebonden door middel van een thio-esterbinding. Deze binding is ontstaan door een condensatiereactie tussen moleculen 18-MEA en SH-groepen van cysteïne-eenheden in keratinemoleculen. Deze reactie verloopt op dezelfde wijze als de condensatie van een zuur en een alcohol.$$, 'inline'),
  ('39956c66-9a2d-4886-bfe8-1576ba47525f', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$hoge pH van haarverf — opzwellen van keratine$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context3.png$$,
   $$Haarverf heeft een hoge pH. Bij deze hoge pH zwellen bepaalde delen van keratine op en dringen pigmentmoleculen tot diep in een haar door. Onderzoekers vermoeden dat het opzwellen van delen van keratine wordt veroorzaakt doordat in de betrokken peptideketens relatief veel aminozuureenheden met zure restgroepen aanwezig zijn.$$, 'inline'),
  ('be994a2a-239e-45f4-b0b7-adfa48d1910d', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$behandeling met waterstofperoxide — redoxreacties in keratine$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context4.png$$,
   $$Voordat haarverf wordt aangebracht, behandelt men soms het haar met waterstofperoxide (H₂O₂). Tijdens deze behandeling treden allerlei redoxreacties op, die leiden tot veranderingen in de structuur van de peptideketens in keratine. Op de uitwerkbijlage is de halfreactie van de peptideketen in keratine onvolledig weergegeven. In de andere halfreactie wordt H₂O₂ omgezet tot OH⁻.$$, 'inline'),
  ('65da1094-527d-405c-9b8f-0ce19f33a8a5', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$uitwerkbijlage vraag 15 en 16 — onvolledige halfreactie peptideketen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context5-uitwerkbijlage-vraag15-16.png$$,
   $$uitwerkbijlage bij vraag 15 en 16: onvolledig weergegeven halfreactie van de peptideketen in keratine (met een S–S-binding tussen twee cysteïne-eenheden als uitgangspunt), aan te vullen tot een complete halfreactievergelijking.$$, 'uitwerkbijlage'),
  ('8618b9ab-db31-4f47-8c73-164cf468fa8e', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$PPD en waterstofperoxide — vorming van stof B en evenwicht met HB+$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context6.png$$,
   $$Een doosje permanente haarverf bevat twee flesjes, die de gebruiker mengt vlak voordat hij de verf aanbrengt. Tijdens het aanbrengen en het intrekken van het mengsel ontstaan pas de uiteindelijke kleurpigmenten. Veelgebruikte componenten van haarverf zijn p-fenyleendiamine (PPD) en waterstofperoxide. PPD wordt door waterstofperoxide omgezet tot stof B. Stof B is een zwakke base. Bij de heersende pH is een klein deel van stof B aanwezig als het geconjugeerde zuur (HB⁺). In onderstaande figuur zijn de omzetting van PPD tot stof B en het evenwicht tussen stof B en HB⁺ weergegeven.$$, 'inline'),
  ('d915aa14-caea-4a08-a804-3e5f73d47a52', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$figuur — omzetting van PPD tot stof B en evenwicht HB+$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context7.png$$,
   $$figuur: omzetting van PPD (benzeenring met twee NH₂-groepen) door oxidatie (onder afsplitsing van 2 H⁺) tot stof B (benzeenring met een NH- en een =NH-groep), en het evenwicht van stof B met het geconjugeerde zuur HB⁺ (waarbij het extra H⁺ zich bindt aan het =NH-stikstofatoom, dat daardoor positief geladen wordt).$$, 'inline'),
  ('71b3c4bf-c714-4790-8335-7768fa2b6494', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$HB+ — sterk elektrofiel deeltje$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context8.png$$,
   $$Het deeltje HB⁺ is een sterk elektrofiel deeltje dat een rol speelt in het verdere mechanisme van de vorming van de uiteindelijke pigmenten.$$, 'inline'),
  ('f1f6558b-c502-44eb-9e3a-80bc0e15b7fa', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$uitwerkbijlage vraag 17 — grensstructuur van HB+$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context9-uitwerkbijlage-vraag17.png$$,
   $$uitwerkbijlage bij vraag 17: onvolledige Lewisstructuur van een grensstructuur van HB⁺ (met de positieve lading op het NH₂-stikstofatoom), aan te vullen, plus ruimte om een andere grensstructuur van HB⁺ te tekenen.$$, 'uitwerkbijlage'),
  ('0357dd12-6e38-4bc7-80b3-9d6c45652881', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$Kz van HB+ is 1,8·10⁻⁶$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context10.png$$,
   $$Door de hoge pH van haarverf is slechts een klein deel van stof B aanwezig als HB⁺. De Kz van HB⁺ is 1,8·10⁻⁶.$$, 'inline'),
  ('c6e3aced-4f4d-47ec-8403-a90f8f1f0f36', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$PPD en 3-aminofenol — vorming bruinrode kleur en paarsrood pigment stof 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context11.png$$,
   $$In een bepaalde soort haarverf is behalve PPD ook de stof 3-aminofenol aanwezig. PPD en 3-aminofenol ondergaan opeenvolgende additie- en oxidatiereacties. Op de uitwerkbijlage zijn de verlopende reacties weergegeven. Het mengsel met PPD en 3-aminofenol leidt tot een bruinrode haarkleur. Het is ook mogelijk om een paarsrood pigment, stof 2, te verkrijgen. Hiertoe wordt een andere beginstof gekozen dan 3-aminofenol. Wanneer in het molecuul 3-aminofenol een H-atoom aan de benzeenring is vervangen door een CH₃-groep, wordt uitsluitend stof 2 gevormd. De C-atomen van 3-aminofenol op de uitwerkbijlage zijn genummerd.$$, 'inline'),
  ('e632195e-e651-4ac8-913c-028cac045423', '78c80bc6-91d5-42d5-9b82-ec90c57dc6ec', $$uitwerkbijlage vraag 19 — genummerde C atomen van 3-aminofenol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-haarverf-context12-uitwerkbijlage-vraag19.png$$,
   $$uitwerkbijlage bij vraag 19: reactieschema van PPD en stof B met 3-aminofenol (genummerde C-atomen 1 t/m 6) via additie en oxidatie tot stof 1 (kleurloos), vervolgens met stof B tot stof 3 (kleurloos) en na oxidatie tot stof 2 (paarsrood) respectievelijk stof 4 (bruin).$$, 'uitwerkbijlage'),

  ('fae95a8c-62ce-425a-bc62-41c4c86c60a2', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$inleiding — Lanzatech-proces, omzetting afvalgassen tot ethanol$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context1.png$$,
   $$Afvalgassen uit de staal- en petrochemische industrie bevatten behalve koolstofdioxide vaak ook veel koolstofmono-oxide. Het bedrijf Lanzatech heeft een proces ontwikkeld waarbij deze afvalgassen worden gemengd met waterstof en andere gassen afkomstig van vergaste biomassa en vergaste kolen. Het verkregen mengsel wordt vervolgens door speciale micro-organismen omgezet tot ethanol (C₂H₆O) en andere alcoholen. De totaalvergelijking van één van de biochemische routes waarmee deze micro-organismen ethanol produceren, is weergegeven met reactie 1.$$, 'inline'),
  ('91acd693-7a86-404e-8ead-22678cfba03b', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$reactie 1 — 6 CO + 3 H2O naar ethanol + 4 CO2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context2.png$$,
   $$reactie 1: 6 CO (g) + 3 H₂O (l) → C₂H₆O (l) + 4 CO₂ (g)$$, 'inline'),
  ('3369139e-3c0a-4db2-87c3-cbbdffc20cb5', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$reactie 2 en CO2-balans van het Lanzatech-proces$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context3.png$$,
   $$Een andere biochemische route kan met reactie 2 worden beschreven: 6 H₂ + 2 CO₂ → 3 H₂O + C₂H₆O. In de bioreactor wordt uiteindelijk alle CO en CO₂ omgezet tot ethanol en andere alcoholen. De opbrengst aan ethanol in het Lanzatech-proces wordt uitgedrukt in MJ. Dit is de hoeveelheid energie die vrijkomt als het geproduceerde ethanol zou worden verbrand. De CO₂-opname door de micro-organismen in het Lanzatech-proces is 81,5 g CO₂ per MJ. De CO₂-uitstoot van de overige processen is 51 g CO₂ per MJ.$$, 'inline'),
  ('c41ae408-c786-4fd2-8731-df099e87cf3d', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$C4-alcoholen — destillatie en vervolgproces naar koolwaterstoffen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context4.png$$,
   $$Het ethanol en de overige alcoholen worden door destillatie gescheiden van het mengsel in de bioreactor. Behalve ethanol worden in de Lanzatech-bioreactor ook butaan-1-ol, butaan-2-ol, 2-methylpropaan-1-ol en 2-methylpropaan-2-ol gevormd door de micro-organismen. Deze C4-alcoholen kunnen in een aansluitend proces worden gebruikt om door additiereacties koolwaterstoffen te produceren met 12 en 16 koolstofatomen in de moleculen. Deze koolwaterstoffen kunnen worden toegevoegd aan kerosine. Dit proces is in onderstaand blokschema weergegeven. Met C4 tot en met C16 is het aantal koolstofatomen in de koolwaterstoffen aangegeven.$$, 'inline'),
  ('658e65ad-6190-45fa-8cd2-d1857fddc39b', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$blokschema — proces van C4-alcoholen naar kerosine-toevoeging$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context5.png$$,
   $$blokschema van het proces: C4-alcoholen gaan naar reactor R1 (vorming van water en C4-alkenen), naar scheidingsruimte S1 (afscheiding van water en onomgezette C4-alcoholen), de C4-alkenen naar reactor R2 (additiereacties tot C4-, C8-, C12- en C16-alkenen) en scheidingsruimte S2 (C4- en C8-alkenen terug naar R2; C12- en C16-alkenen door naar R3), reactor R3 (hydrogenering met H₂ tot alkanen, met recirculatie) en scheidingsruimte S3 (afscheiding van waterstof, terug naar R3; het product C12/C16 gaat naar kerosine). C12/C16* is een mengsel van alkanen en alkenen.$$, 'inline'),
  ('7414d0de-d6e8-4fbd-bdfe-c2f3118f6956', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$R1 — omzetting C4-alcoholen tot C4-alkenen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context6.png$$,
   $$In reactor 1 (R1) worden de C4-alcoholen onvolledig omgezet tot de C4-alkenen methylpropeen, but-1-een en but-2-een. Hierbij ontstaat ook water.$$, 'inline'),
  ('731b403e-d653-4bfa-bc94-aafb942ce6c3', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$S1 — scheiding van C4-alkenen, water en onomgezette alcoholen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context7.png$$,
   $$Het mengsel afkomstig uit R1 wordt in scheidingsruimte 1 (S1) afgekoeld. Hierdoor worden de C4-alkenen afgescheiden van het water en van de C4-alcoholen die niet hebben gereageerd.$$, 'inline'),
  ('0b902714-1f84-40f7-bc4c-c25c6ea796e2', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$R2 en S2 — additiereacties en scheiding van alkenen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context8.png$$,
   $$In R2 vinden additiereacties plaats tussen de C4-alkenen, waarbij alkenen met 8, 12 of 16 C-atomen worden gevormd. In S2 wordt het verkregen mengsel van alkenen gescheiden in twee fracties. De fractie met de C4- en de C8-alkenen wordt teruggevoerd naar R2. De fractie met de C12- en de C16-alkenen wordt doorgevoerd naar R3. De scheiding in S2 kan eenvoudig plaatsvinden omdat bij de gebruikte omstandigheden in de scheidingsruimte steeds één fractie in de vloeibare fase is en de andere fractie in de gasfase.$$, 'inline'),
  ('26adc6d3-57dc-4f3f-ab57-ac326a03b0bb', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$R3 en S3 — hydrogenering van alkenen en recirculatie waterstof$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context9.png$$,
   $$In R3 reageren de gevormde alkenen onvolledig met een overmaat waterstof tot alkanen. In S3 wordt de overmaat waterstof gescheiden van de rest van het mengsel en teruggevoerd naar R3. Een deel van het mengsel afkomstig uit R3 wordt opgeslagen als een product dat kan worden gebruikt als toevoeging aan kerosine. Het overgebleven deel wordt weer naar R3 teruggevoerd. Deze recirculatie zorgt voor een hoger rendement in R3.$$, 'inline'),
  ('bc07256a-84aa-4172-9f40-e53c6dcab86b', '355a4bc0-933e-4aad-bab9-9dbce023e7a3', $$R2 — 1,4·10³ mol C4-alkenen per minuut, 98% omzetting$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-vwo-2018-ii-afvalgas-naar-brandstof-context10.png$$,
   $$In R2 wordt per minuut 1,4·10³ mol C4-alkenen omgezet tot evenveel mol C12- als C16-alkenen. In het product dat uiteindelijk wordt opgeslagen is 98% van de C12- en de C16-alkenen omgezet tot alkanen.$$, 'inline');

