  ('dab9d627-afe0-4b1a-b743-6ffb0528feca', '44dfd307-ebcf-4a19-92e1-fedf33c0361b', 9,
   '[{"domain": "Materie", "subdomain": "Deeltjesmodellen"}]'::jsonb,
   '["elektronenconfiguratie", "elektronenschil", "oxide-ion", "molybdeen-ion", "POM3–"]'::jsonb,
